 * Out-of-office coverage.
 *
 * A member is away from `startsAt` inclusive until `endsAt` exclusive. Coverage
 * is a single hop: when the delegate is away too, work still stops with them.
 */
import { now, parseIso } from "@/lib/date";
import * as absenceRepo from "@/server/repositories/absence-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { MemberAbsence } from "@/types/member";

/** True while `at` is inside the window. A window that has not started yet is not away. */
export function isAwayAt(
  absence: Pick<MemberAbsence, "startsAt" | "endsAt">,
  at: IsoTimestamp,
): boolean {
  const instant = parseIso(at).getTime();
  return (
    parseIso(absence.startsAt).getTime() <= instant &&
    instant < parseIso(absence.endsAt).getTime()
  );
}

/** A scheduled window that has not started is still open. The end itself is closed. */
export function absenceHasNotEnded(
  absence: Pick<MemberAbsence, "endsAt">,
  at: IsoTimestamp,
): boolean {
  return parseIso(at).getTime() < parseIso(absence.endsAt).getTime();
}

/**
 * The active member covering `userId` at `at`, or null when `userId` is not
 * away, named nobody, or named someone who has left. Does not follow a chain.
 */
export async function coveringDelegate(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<UserId | null> {
  const absence = await absenceRepo.findAbsence(orgId, userId);
  if (!absence || !isAwayAt(absence, at) || absence.delegateUserId === null) {
    return null;
  }
  if (absence.delegateUserId === userId) return null;

  const delegate = await memberRepo.findMember(orgId, absence.delegateUserId);
  if (!delegate || delegate.status !== "active") return null;
  return absence.delegateUserId;
}

/**
 * Assignee to store for a new assignment. Taking an issue yourself is never
 * redirected; everyone else's coverage is one hop at `at` (defaults to now).
 */
export async function resolveAssignee(
  orgId: OrgId,
  assigneeId: UserId | null,
  actorId: UserId,
  at: IsoTimestamp = now(),
): Promise<UserId | null> {
  if (assigneeId === null || assigneeId === actorId) return assigneeId;
  const delegate = await coveringDelegate(orgId, assigneeId, at);
  return delegate ?? assigneeId;
}
