{"type":"SearchReplace","EditsApplied":{"old_string":"/**
 * Turns a (user, org) pair into the `Actor` every service method takes. The
 * only place an `Actor` is minted from stored state — jobs and the session
 * layer both come through here.
 */","new_string":"/**
 * Replaces the member's out-of-office window. The end must be strictly after
 * the start, and a delegate — when named — is another active member of this
 * workspace. Whoever may change roles may set anyone's window; everyone else
 * only their own.
 */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);
  const member = await requireActiveMember(input.orgId, input.userId);
  assertMayEditAbsence(actor, member);

  if (parseIso(input.endsAt).getTime() <= parseIso(input.startsAt).getTime()) {
    throw new Error("Absence end must be after the start");
  }

  const delegateUserId = input.delegateUserId ?? null;
  if (delegateUserId !== null) {
    if (delegateUserId === input.userId) {
      throw new Error("A member cannot delegate their absence to themselves");
    }
    await requireActiveMember(input.orgId, delegateUserId);
  }

  return absenceRepo.upsertAbsence({
    orgId: input.orgId,
    userId: input.userId,
    delegateUserId,
    startsAt: input.startsAt,
    endsAt: input.endsAt,
    note: input.note ?? null,
  });
}

/** Drops the window. Clearing one that was never set is fine. */
export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);
  const member = await requireActiveMember(orgId, userId);
  assertMayEditAbsence(actor, member);
  await absenceRepo.deleteAbsence(orgId, userId);
}

/**
 * The stored window until it ends, including one that has not started yet.
 * Null once it has ended or when none is set.
 */
export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);
  await requireActiveMember(orgId, userId);
  assertCan(actor, "member:read", orgResource(orgId));

  const stored = await absenceRepo.findAbsence(orgId, userId);
  if (!stored || !absenceHasNotEnded(stored, now())) return null;
  return stored;
}

