/**
 * Temporary coverage for out-of-office delegation. Deleted after verification.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { setAbsenceSchema } from "@/schemas/member";
import * as memberRepo from "@/server/repositories/member-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import { NotFoundError } from "@/server/services/_support";
import { emit } from "@/lib/event-bus";
import { toIsoTimestamp } from "@/types/common";
import {
  createTenant,
  issueInput,
  useTemporaryDatabase,
} from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId, IsoTimestamp, UserId } from "@/types/common";
import type { Actor } from "@/types/member";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

function window(
  orgId: Tenant["org"]["id"],
  userId: UserId,
  overrides: Record<string, unknown> = {},
) {
  return setAbsenceSchema.parse({
    orgId,
    userId,
    startsAt: new Date(Date.now() - 60_000).toISOString(),
    endsAt: new Date(Date.now() + 86_400_000).toISOString(),
    ...overrides,
  });
}

async function mentions(tenant: Tenant, recipientId: UserId, kind: "comment_mention" | "issue_assigned" | "issue_overdue") {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: [kind],
    limit: 25,
    cursor: null,
  });
  return page.items;
}

describe("member absence", () => {
  it("stores, replaces, reads a scheduled window, and clears", async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date("2026-06-01T12:00:00.000Z"));
    const tenant = await createTenant("abs-store");

    const scheduled = await memberService.setAbsence(
      tenant.actors.member,
      setAbsenceSchema.parse({
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        startsAt: "2026-06-02T00:00:00.000Z",
        endsAt: "2026-06-03T00:00:00.000Z",
        note: "out",
      }),
    );
    expect(scheduled).toEqual({
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: null,
      startsAt: "2026-06-02T00:00:00.000Z",
      endsAt: "2026-06-03T00:00:00.000Z",
      note: "out",
    });
    expect(
      await memberService.getAbsence(
        tenant.actors.viewer,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).toEqual(scheduled);

    const replaced = await memberService.setAbsence(
      tenant.actors.admin,
      setAbsenceSchema.parse({
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        delegateUserId: tenant.userIds.admin,
        startsAt: "2026-06-01T00:00:00.000Z",
        endsAt: "2026-06-01T12:00:00.000Z",
        note: null,
      }),
    );
    expect(replaced.delegateUserId).toBe(tenant.userIds.admin);
    expect(replaced.note).toBeNull();
    // The end does not count, so this window has ended.
    expect(
      await memberService.getAbsence(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).toBeNull();

    await memberService.clearAbsence(
      tenant.actors.member,
      tenant.org.id,
      tenant.userIds.member,
    );
    await memberService.clearAbsence(
      tenant.actors.member,
      tenant.org.id,
      tenant.userIds.member,
    );
    expect(
      await memberService.getAbsence(
        tenant.actors.member,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).toBeNull();
  });

  it("rejects a window that does not end after it starts and a self delegate", async () => {
    const tenant = await createTenant("abs-validate");
    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        window(tenant.org.id, tenant.userIds.member, {
          startsAt: "2026-06-02T00:00:00.000Z",
          endsAt: "2026-06-02T00:00:00.000Z",
        }),
      ),
    ).rejects.toThrow(/after the start/);

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        window(tenant.org.id, tenant.userIds.member, {
          delegateUserId: tenant.userIds.member,
        }),
      ),
    ).rejects.toThrow(/themselves/);
  });

  it("requires an active member and an active delegate, and gates who may edit", async () => {
    const tenant = await createTenant("abs-auth");
    const other = await createTenant("abs-auth-other");

    await expect(
      memberService.setAbsence(
        other.actors.owner,
        window(tenant.org.id, tenant.userIds.member),
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      memberService.getAbsence(
        other.actors.owner,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      memberService.clearAbsence(
        other.actors.owner,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        window(tenant.org.id, tenant.userIds.member, {
          delegateUserId: other.userIds.admin,
        }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        window(tenant.org.id, other.userIds.member),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        window(tenant.org.id, tenant.userIds.admin),
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const setByAdmin = await memberService.setAbsence(
      tenant.actors.admin,
      window(tenant.org.id, tenant.userIds.viewer, {
        delegateUserId: tenant.userIds.member,
        note: "covering",
      }),
    );
    expect(setByAdmin.delegateUserId).toBe(tenant.userIds.member);

    const viewerMember = await memberRepo.findMember(
      tenant.org.id,
      tenant.userIds.viewer,
    );
    if (!viewerMember) throw new Error("viewer missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewerMember.id,
    });
    await expect(
      memberService.getAbsence(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.viewer,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("drops the absence with the member and drops a removed delegate", async () => {
    const tenant = await createTenant("abs-remove");
    await memberService.setAbsence(
      tenant.actors.member,
      window(tenant.org.id, tenant.userIds.member, {
        delegateUserId: tenant.userIds.admin,
      }),
    );
    await memberService.setAbsence(
      tenant.actors.admin,
      window(tenant.org.id, tenant.userIds.admin, {
        delegateUserId: tenant.userIds.owner,
      }),
    );

    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    if (!admin) throw new Error("admin missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin.id,
    });

    const memberWindow = await memberService.getAbsence(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );
    expect(memberWindow?.delegateUserId).toBeNull();
    await expect(
      memberService.getAbsence(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.admin,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("keeps an absence inside its own workspace", async () => {
    const home = await createTenant("abs-home");
    const away = await createTenant("abs-away");
    await memberRepo.insertMember(
      away.org.id,
      home.userIds.member,
      "member",
      null,
    );
    await memberService.setAbsence(
      home.actors.member,
      window(home.org.id, home.userIds.member, {
        delegateUserId: home.userIds.admin,
      }),
    );

    const actorInAway: Actor = {
      userId: home.userIds.member,
      orgId: away.org.id,
      role: "member",
    };
    expect(
      await memberService.getAbsence(
        away.actors.owner,
        away.org.id,
        home.userIds.member,
      ),
    ).toBeNull();

    const issue = await issueService.createIssue(
      actorInAway,
      issueInput(away.org.id, away.project.id, {
        title: "Cross workspace",
        assigneeId: home.userIds.member,
      }),
    );
    expect(issue.assigneeId).toBe(home.userIds.member);
  });

  it("redirects new assignments one hop, except a self-assign", async () => {
    const tenant = await createTenant("abs-assign");
    const standIn = await userRepo.insertUser({
      email: "standin@abs-assign.test",
      name: "Stand In",
      passwordHash: "seed",
    });
    await memberRepo.insertMember(tenant.org.id, standIn.id, "viewer", null);
    const standInActor: Actor = {
      userId: standIn.id,
      orgId: tenant.org.id,
      role: "viewer",
    };

    await memberService.setAbsence(
      tenant.actors.viewer,
      window(tenant.org.id, tenant.userIds.viewer, {
        delegateUserId: standIn.id,
      }),
    );
    await memberService.setAbsence(
      tenant.actors.admin,
      window(tenant.org.id, tenant.userIds.admin, {
        delegateUserId: tenant.userIds.owner,
      }),
    );
    // Chain: viewer -> stand-in is not away. Separate chain member -> admin -> owner.
    await memberService.setAbsence(
      tenant.actors.member,
      window(tenant.org.id, tenant.userIds.member, {
        delegateUserId: tenant.userIds.admin,
      }),
    );

    const created = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Created for someone away",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(created.assigneeId).toBe(tenant.userIds.admin);

    const selfCreated = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Created for myself",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(selfCreated.assigneeId).toBe(tenant.userIds.member);

    const existing = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Already mine",
        assigneeId: tenant.userIds.owner,
      }),
    );
    expect(existing.assigneeId).toBe(tenant.userIds.owner);

    const assigned = await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: existing.id,
      assigneeId: tenant.userIds.viewer,
    });
    expect(assigned.assigneeId).toBe(standIn.id);

    await expect(
      issueService.updateIssue(standInActor, {
        orgId: tenant.org.id,
        issueId: existing.id,
        title: "Delegate can edit",
      }),
    ).resolves.toMatchObject({ assigneeId: standIn.id, title: "Delegate can edit" });
    await expect(
      issueService.updateIssue(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: existing.id,
        title: "Away viewer cannot",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const chained = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: selfCreated.id,
      assigneeId: tenant.userIds.member,
    });
    expect(chained.assigneeId).toBe(tenant.userIds.admin);

    const taken = await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: created.id,
      assigneeId: tenant.userIds.member,
    });
    expect(taken.assigneeId).toBe(tenant.userIds.member);

    const alertsForStandIn = await mentions(tenant, standIn.id, "issue_assigned");
    const alertsForViewer = await mentions(
      tenant,
      tenant.userIds.viewer,
      "issue_assigned",
    );
    expect(alertsForStandIn.length).toBeGreaterThan(0);
    expect(alertsForViewer).toHaveLength(0);
  });

  it("sends overdue alerts to the delegate and mentions to both", async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date("2026-06-01T12:00:00.000Z"));
    const tenant = await createTenant("abs-alerts");
    await memberService.setAbsence(
      tenant.actors.member,
      setAbsenceSchema.parse({
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        delegateUserId: tenant.userIds.admin,
        startsAt: "2026-06-01T00:00:00.000Z",
        endsAt: "2026-06-02T00:00:00.000Z",
      }),
    );

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Stays with me",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(issue.assigneeId).toBe(tenant.userIds.member);

    const occurredAt = toIsoTimestamp(new Date("2026-06-01T12:00:00.000Z"));
    await emit("issue.overdue", {
      orgId: tenant.org.id,
      actorId: null,
      occurredAt,
      issueId: issue.id,
      projectId: issue.projectId,
      dueAt: toIsoTimestamp(new Date("2026-05-01T00:00:00.000Z")),
      assigneeId: tenant.userIds.member,
    });

    expect(await mentions(tenant, tenant.userIds.admin, "issue_overdue")).toHaveLength(1);
    expect(await mentions(tenant, tenant.userIds.member, "issue_overdue")).toHaveLength(0);

    await emit("comment.created", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      occurredAt,
      commentId: "01HZZZCCCCCCCCCCCCCCCCCCCC" as CommentId,
      issueId: issue.id,
      mentionedUserIds: [tenant.userIds.member, tenant.userIds.admin],
    });

    expect(await mentions(tenant, tenant.userIds.member, "comment_mention")).toHaveLength(1);
    expect(await mentions(tenant, tenant.userIds.admin, "comment_mention")).toHaveLength(1);

    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.admin,
      kind: "comment_mention",
      inApp: false,
      email: false,
      digestOnly: false,
    });

    await emit("comment.created", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      occurredAt,
      commentId: "01HZZZCCCCCCCCCCCCCCCCCCCD" as CommentId,
      issueId: issue.id,
      mentionedUserIds: [tenant.userIds.member],
    });

    // Author is the delegate, so they are not alerted; the mentioned member is.
    // The muted preference applies only to the delegate, who was the author anyway.
    expect(await mentions(tenant, tenant.userIds.member, "comment_mention")).toHaveLength(2);
    expect(await mentions(tenant, tenant.userIds.admin, "comment_mention")).toHaveLength(1);

    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      kind: "comment_mention",
      inApp: false,
      email: false,
      digestOnly: false,
    });
    await memberService.setAbsence(
      tenant.actors.viewer,
      setAbsenceSchema.parse({
        orgId: tenant.org.id,
        userId: tenant.userIds.viewer,
        delegateUserId: tenant.userIds.owner,
