      await memberService.getAbsence(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).toBeNull();

    await memberService.clearAbsence(
      tenant.actors.member,
      tenant.org.id,
      tenant.userIds.member,
    );
    await memberService.clearAbsence(
      tenant.actors.member,
      tenant.org.id,
      tenant.userIds.member,
    );
    expect(
      await memberService.getAbsence(
        tenant.actors.member,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).toBeNull();
