      ),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      memberService.clearAbsence(
        other.actors.owner,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        window(tenant.org.id, tenant.userIds.member, {
          delegateUserId: other.userIds.admin,
        }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        window(tenant.org.id, other.userIds.member),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        window(tenant.org.id, tenant.userIds.admin),
